def transform(grid):
    """Continue the terminal foreground rhythm of each horizontal band."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Find horizontal bands separated by blank rows. The furthest-reaching
    # rows establish the continuation edge; sustained terminal runs extend
    # across the suffix. A row just one cell short of that edge continues its
    # alternating terminal rhythm.
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        end = r
        right = [max((c for c, v in enumerate(grid[rr]) if v != bg), default=-1)
                 for rr in range(start, end)]
        farthest = max(right)
        for rr, edge in zip(range(start, end), right):
            if edge < 0:
                continue
            run = 0
            c = edge
            while c >= 0 and grid[rr][c] != bg:
                run += 1
                c -= 1
            if edge == farthest and run >= 2:
                for c in range(edge + 1, w):
                    if grid[rr][c] == bg:
                        out[rr][c] = 1
            elif edge == farthest and run == 1:
                # A lone terminal pixel in a tied edge is extended only at
                # the first row of the band, as in the sparse pattern case.
                if rr == start and edge + 1 < w and grid[rr][edge + 1] == bg:
                    out[rr][edge + 1] = 1
            elif edge == farthest - 1 and run >= 2:
                for c in range(edge + 2, w, 2):
                    if grid[rr][c] == bg:
                        out[rr][c] = 1
    return out

